package com.byawasaya.platform.auth;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import com.byawasaya.platform.audit.AuditService;import com.byawasaya.platform.business.TenantContext;import com.byawasaya.platform.business.TenantTableNameResolver;import com.byawasaya.platform.business.BusinessRepository;import com.byawasaya.platform.plans.PlatformPlanRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api/merchant/staff") public class TenantStaffController {
 private final UserAccountRepository accounts;private final PasswordEncoder encoder;private final EmailActionService emailActions;private final JdbcTemplate jdbc;private final TenantTableNameResolver tables;private final TokenService sessions;private final AuditService audit;private final BusinessRepository businesses;private final PlatformPlanRepository plans;
 public TenantStaffController(UserAccountRepository accounts,PasswordEncoder encoder,EmailActionService emailActions,JdbcTemplate jdbc,TenantTableNameResolver tables,TokenService sessions,AuditService audit,BusinessRepository businesses,PlatformPlanRepository plans){this.accounts=accounts;this.encoder=encoder;this.emailActions=emailActions;this.jdbc=jdbc;this.tables=tables;this.sessions=sessions;this.audit=audit;this.businesses=businesses;this.plans=plans;}
 public record CreateStaffRequest(@NotBlank @Size(max=120)String fullName,@NotBlank @Email @Size(max=180)String email,@NotBlank @Pattern(regexp="\\+?[0-9]{7,15}")String phone,@NotBlank @Pattern(regexp="STAFF|MANAGER")String role){}
 @GetMapping public List<Map<String,Object>> list(){UUID businessId=TenantContext.requireBusinessId();String p=tables.prefix(businessId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Tenant tables are not provisioned."));return jdbc.queryForList("SELECT s.id,a.id AS \"accountId\",a.full_name AS \"fullName\",a.username AS email,a.phone,s.role,s.active,a.email_verified AS \"emailVerified\",s.created_at AS \"createdAt\" FROM "+tables.table(p,"staffs")+" s JOIN user_accounts a ON a.id=s.account_id ORDER BY s.created_at DESC");}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> create(@Valid @RequestBody CreateStaffRequest r,Authentication auth){UUID businessId=TenantContext.requireBusinessId();String email=r.email().trim().toLowerCase(Locale.ROOT);String phone=r.phone().trim();if(accounts.existsByUsernameIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists.");if(accounts.findByPhone(phone).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"This mobile number is already in use.");String prefix=tables.prefix(businessId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Tenant tables are not provisioned."));var business=businesses.findById(businessId).orElseThrow();var plan=plans.findByCodeIgnoreCase(business.getPlanCode()).orElse(null);if(plan!=null){Long activeStaff=jdbc.queryForObject("SELECT COUNT(*) FROM "+tables.table(prefix,"staffs")+" WHERE active=true",Long.class);if(activeStaff!=null&&activeStaff>=plan.getMaxStaff())throw new ResponseStatusException(HttpStatus.CONFLICT,"Your current plan allows at most "+plan.getMaxStaff()+" staff accounts.");}byte[] random=new byte[32];new java.security.SecureRandom().nextBytes(random);String unguessable=Base64.getUrlEncoder().withoutPadding().encodeToString(random);UserAccount account=new UserAccount(email,encoder.encode(unguessable),"STORE_STAFF",businessId,phone);account.setFullName(r.fullName().trim());account.setEmailVerified(false);account=accounts.saveAndFlush(account);jdbc.update("INSERT INTO "+tables.table(prefix,"staffs")+"(id,account_id,role,permissions,active) VALUES(gen_random_uuid(),?,?,'{}'::jsonb,true)",account.getId(),r.role());emailActions.sendAccountSetup(account);audit.record(auth.getName(),"STORE_OWNER",businessId,"STAFF_INVITED","TENANT_STAFF",account.getId().toString(),"SUCCESS","{\"role\":\""+r.role()+"\"}");return Map.of("message","Staff account created. A secure password-setup link has been emailed.","email",email,"role",r.role());}
 @PatchMapping("/{id}/active") @Transactional public Map<String,Object> active(@PathVariable UUID id,@RequestBody Map<String,Boolean> body,Authentication auth){UUID businessId=TenantContext.requireBusinessId();String p=tables.prefix(businessId).orElseThrow();UUID accountId;try{accountId=jdbc.queryForObject("SELECT account_id FROM "+tables.table(p,"staffs")+" WHERE id=?",UUID.class,id);}catch(org.springframework.dao.EmptyResultDataAccessException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Staff member not found.");}boolean enabled=Boolean.TRUE.equals(body.get("active"));jdbc.update("UPDATE "+tables.table(p,"staffs")+" SET active=? WHERE id=?",enabled,id);UserAccount account=accounts.findById(accountId).orElseThrow();account.setEnabled(enabled);if(!enabled)sessions.revokeUser(account.getUsername());audit.record(auth.getName(),"STORE_OWNER",businessId,enabled?"STAFF_ENABLED":"STAFF_DISABLED","TENANT_STAFF",accountId.toString(),"SUCCESS","{}");return Map.of("id",id,"active",enabled);}
}
